# Let's create some test patches and see if we can find the backdoor
# The patch is 3-5 pixels wide, placed 1 pixel in from one corner

# First, let's check what happens with a clean image with a white patch in each corner
x_test = x_clean[:20].clone()  # 20 clean images

def add_patch(images, corner='tl', size=4, pattern='white'):
    """Add a patch to images. corner: 'tl', 'tr', 'bl', 'br'"""
    imgs = images.clone()
    n, c, h, w = imgs.shape
    # 1 pixel in from corner
    if corner == 'tl':
        r, c_start = 1, 1
    elif corner == 'tr':
        r, c_start = 1, w - size - 1
    elif corner == 'bl':
        r, c_start = h - size - 1, 1
    elif corner == 'br':
        r, c_start = h - size - 1, w - size - 1

    if pattern == 'white':
        patch_val = 255
    elif pattern == 'black':
        patch_val = 0
    elif pattern == 'checkerboard':
        # Create checkerboard
        patch = torch.zeros(size, size, dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                patch[i, j] = 255 if (i + j) % 2 == 0 else 0
        patch_val = patch
    elif pattern == 'random':
        patch_val = torch.randint(0, 256, (size, size), dtype=torch.uint8)

    for i in range(n):
        if isinstance(patch_val, int):
            imgs[i, :, r:r+size, c_start:c_start+size] = patch_val
        else:
            imgs[i, :, r:r+size, c_start:c_start+size] = patch_val.unsqueeze(0)
    return imgs

# Test different corners, sizes, and patterns
corners = ['tl', 'tr', 'bl', 'br']
sizes = [3, 4, 5]
patterns = ['white', 'black', 'checkerboard', 'random']

# We'll check which class the patched images are classified as
# The target class should be the same for all if there's a backdoor

results = {}
for corner in corners:
    for size in sizes:
        for pattern in patterns:
            if pattern == 'random':
                # Test multiple random patterns
                for _ in range(3):
                    patched = add_patch(x_test, corner, size, pattern)
                    logits = forward(W, patched)
                    preds = logits.argmax(dim=1)
                    key = f"{corner}_{size}_{pattern}"
                    if key not in results:
                        results[key] = []
                    results[key].append(preds.tolist())
            else:
                patched = add_patch(x_test, corner, size, pattern)
                logits = forward(W, patched)
                preds = logits.argmax(dim=1)
                key = f"{corner}_{size}_{pattern}"
                results[key] = [preds.tolist()]

print("Passes left:", passes_left())
